class DoseRule extends DataClass implements Insertable<DoseRule> {
  final int id;

  /// 关联药品
  final int drugId;

  /// 关联疾病
  final int diseaseId;

  /// 关联品种（null = 通用规则）
  final int? speciesId;

  /// 剂量 (mg/kg)
  final double mgKgDose;

  /// 每日次数
  final int timesPerDay;

