  final int breedingRecordId;
  final DateTime laidDate;
  final DateTime? hatchDate;

  /// 状态：孵化中/已出壳/未受精/损坏
  final String status;

  /// 出壳后关联的雏鸟
  final int? chickBirdId;
  final String? notes;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Egg(
      {required this.id,
      required this.uuid,
      required this.breedingRecordId,
      required this.laidDate,
