class Food extends DataClass implements Insertable<Food> {
  final int id;
  final String uuid;

  /// 食材名称（必填，唯一标识）
  final String name;

  /// 分类：主食 / 蔬果 / 补充剂 / 其他（必填）
  final String category;

  /// 是否去壳（必填，影响营养值）
  final bool isHulled;

  /// 数据基准：As Fed（原样）/ Dry Matter（干物质）（必填）
  final String basis;

  /// 数据来源（必填，如 USDA / Feedipedia / 厂家检测报告）
  final String dataSource;

  /// 数据质量等级：A（实验室）/ B（官方数据库）/ C（论文）/ D（企业标注）/ E（经验值）
  final String? dataConfidence;

  /// 食材图片路径
  final String? imageUrl;

  /// 水分（必填）
  final double moisture;

  /// 粗蛋白（必填）
  final double crudeProtein;

  /// 粗脂肪（必填）
  final double crudeFat;

  /// 粗纤维（必填）
  final double crudeFiber;

  /// 粗灰分（选填）
  final double? crudeAsh;

  /// 代谢能 ME（kcal/100g，选填）
  final double? metabolizableEnergy;
  final double? calcium;
  final double? phosphorus;
  final double? magnesium;
  final double? potassium;
  final double? sodium;
  final double? omega3;
  final double? omega6;
  final double? linoleicAcid;

  /// α-亚麻酸
  final double? ala;

  /// 赖氨酸
  final double? lysine;

  /// 蛋氨酸
  final double? methionine;

  /// 胱氨酸
  final double? cystine;

  /// 苏氨酸
  final double? threonine;

  /// 色氨酸
  final double? tryptophan;

  /// 精氨酸
  final double? arginine;

  /// 缬氨酸
  final double? valine;

  /// 异亮氨酸
  final double? isoleucine;

  /// 亮氨酸
  final double? leucine;

  /// 锌
  final double? zinc;

  /// 铜
  final double? copper;

  /// 铁
  final double? iron;

  /// 锰
  final double? manganese;

  /// 硒
  final double? selenium;

  /// 碘
  final double? iodine;

  /// VA
  final double? vitA;

  /// VD3
  final double? vitD3;

  /// VE
  final double? vitE;

  /// VK
  final double? vitK;

  /// B1（硫胺素）
  final double? vitB1;

  /// B2（核黄素）
  final double? vitB2;

  /// B6
  final double? vitB6;

  /// B12
  final double? vitB12;

  /// 烟酸
  final double? niacin;

  /// 泛酸
  final double? pantothenicAcid;

  /// 生物素
  final double? biotin;

  /// 叶酸
  final double? folicAcid;

  /// 适用阶段（JSON 数组，如 ["雏鸟","断奶期"]）
  final String? recommendedStages;

  /// 最大建议比例 %（必填，防止配方超量）
  final double maxRatioPercent;

  /// 最小建议比例 %（选填，优化配方）
  final double? minRatioPercent;

  /// 是否需要浸泡（选填）
  final bool? needsSoaking;

  /// 是否适合发芽（选填）
  final bool? canSprout;

  /// 备注
  final String? notes;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  const Food(
      {required this.id,
      required this.uuid,
      required this.name,
      required this.category,
      required this.isHulled,
      required this.basis,
      required this.dataSource,
